from django.db import migrations, models


def forwards_sync_review_status(apps, schema_editor):
    """#jxr 数据迁移：老数据只有 is_enable 布尔值，回填成对应的三态。

    规则：is_enable=True → approved；is_enable=False → pending（保持“待审”而非“拒绝”，
    因为历史数据里隐藏的评论多数是还没审，而不是明确拒绝）。
    """
    Comment = apps.get_model('comments', 'Comment')
    Comment.objects.filter(is_enable=True).update(review_status='approved')
    Comment.objects.filter(is_enable=False).update(review_status='pending')


def backwards_sync_review_status(apps, schema_editor):
    """#jxr 回滚：把 approved 反向写回 is_enable，其余状态一律视为不展示。"""
    Comment = apps.get_model('comments', 'Comment')
    Comment.objects.filter(review_status='approved').update(is_enable=True)
    Comment.objects.exclude(review_status='approved').update(is_enable=False)


